><input type="hidden" name="action" value="delete"><button class="icon-button danger" aria-label="Hapus <?=e($row[$meta['key']])?>"><?=icon('trash')?></button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?=count($meta['fields'])+2?>"><div class="empty-state"><?=icon($module==='karyawan'?'users':'building')?><strong><?=$search!==''?'Tidak ada hasil pencarian':'Belum ada data di sini'?></strong><p><?=$search!==''?'Coba kata pencarian yang berbeda.':'Tambahkan data pertama atau impor database lama.'?></p><a href="<?=e(url('master/'.$module,['new'=>1]))?>" class="btn btn-primary btn-sm"><?=icon('plus')?> Tambah data</a></div></td></tr><?php endif;?></tbody></table></div><?php if($total>25):?><div class="table-pagination"><span>Halaman <?=$page?> dari <?=(int)ceil($total/25)?></span><div><?php if($page>1):?><a class="btn btn-light btn-sm" href="<?=url('master/'.$module,['page'=>$page-1,'q'=>$search])?>">Sebelumnya</a><?php endif;?><?php if($page*25<$total):?><a class="btn btn-light btn-sm" href="<?=url('master/'.$module,['page'=>$page+1,'q'=>$search])?>">Berikutnya</a><?php endif;?></div></div><?php endif;?></section>
